              {totalAssigned}
            </p>
          </div>
        </div>
      </Card>

      <Card className="p-6">
        <div className="flex items-center gap-4">
          <div className="p-3 rounded-lg bg-chart-2/10">
            <CheckCircle className="w-6 h-6 text-chart-2" />
